WITH fixes(slug,pos,q,a,why) AS (VALUES ('pcac-2026-portugues-13-variacao-figuras-linguagem-tecnologia',1,'O uso de ''tu'' em uma região e ''você'' em outra pode exemplificar variação diatópica.',true,'Certo. A variação diatópica relaciona-se ao espaço geográfico. A preferência por formas de tratamento pode variar entre regiões; isso não significa que uma região fale português errado.'),
('pcac-2026-portugues-13-variacao-figuras-linguagem-tecnologia',2,'A mudança de significado de uma palavra ao longo dos séculos é exemplo de variação diacrônica.',true,'Certo. Diacrônico significa observar a língua em diferentes momentos históricos. Mudanças de sentido e de grafia podem ser estudadas nessa perspectiva.'),
('pcac-2026-portugues-13-variacao-figuras-linguagem-tecnologia',3,'A existência de uma norma-padrão elimina a legitimidade das variedades linguísticas regionais.',false,'Errado. A norma-padrão é referência de determinados contextos formais, mas as variedades regionais possuem regras e usos próprios. Adequação ao contexto não equivale a negar a diversidade linguística.'),
('pcac-2026-portugues-13-variacao-figuras-linguagem-tecnologia',4,'A escolha entre linguagem coloquial e formal pode depender do destinatário e da finalidade do texto.',true,'Certo. Em mensagem a um amigo, marcas de informalidade podem ser adequadas; em ofício administrativo, exige-se registro formal e clareza. A situação comunicativa orienta a escolha.'),
('pcac-2026-portugues-13-variacao-figuras-linguagem-tecnologia',6,'A expressão ''um silêncio ensurdecedor'' é exemplo de paradoxo.',true,'Certo. O paradoxo reúne ideias aparentemente contraditórias: silêncio e ensurdecedor. Na antítese, há oposição entre ideias sem necessariamente produzir essa aparente impossibilidade.'),
('pcac-2026-portugues-13-variacao-figuras-linguagem-tecnologia',7,'Um leitor pode chegar à mesma página digital por caminhos distintos ao seguir hiperlinks.',true,'Certo. Os hiperlinks conectam documentos ou seções, permitindo percursos de leitura não lineares. A ordem de navegação depende das escolhas do leitor.'),
('pcac-2026-portugues-13-variacao-figuras-linguagem-tecnologia',8,'Uma reportagem que combina texto escrito, fotografias e áudio utiliza recursos multimodais.',true,'Certo. A multimodalidade combina diferentes modos de expressão, como linguagem verbal, imagens e sons. Não se restringe à presença de links.'),
('pcac-2026-portugues-07-ortografia-acentuacao-pontuacao',4,'Em ''Os servidores, após a reunião, retornaram ao trabalho'', as vírgulas isolam um termo intercalado sem separar indevidamente sujeito e verbo.',true,'Certo. A expressão adverbial ''após a reunião'' está intercalada entre sujeito e verbo e pode ser isolada por vírgulas. A pontuação não separa livremente o sujeito de seu predicado.'),
('pcac-2026-portugues-07-ortografia-acentuacao-pontuacao',5,'Em ''Os candidatos, que chegaram cedo, entraram'', as vírgulas marcam uma oração adjetiva explicativa.',true,'Certo. As vírgulas apresentam ''que chegaram cedo'' como informação explicativa sobre o conjunto mencionado. Sem vírgulas, a oração pode restringir quais candidatos entraram.'),
('pcac-2026-portugues-12-regencia-pronomes-crase',1,'Em ''Os estudantes assistiram ao debate'', a preposição ''a'' decorre da regência tradicional de assistir no sentido de presenciar.',true,'Certo. Na norma-padrão tradicional, ''assistir'' no sentido de ver ou presenciar pede preposição ''a''. Por isso, escreve-se ''assistiram ao debate''.'),
('pcac-2026-portugues-12-regencia-pronomes-crase',8,'Em ''O servidor obedeceu à ordem'', o acento grave indica fusão da preposição ''a'' com o artigo feminino ''a''.',true,'Certo. O verbo ''obedecer'' rege a preposição ''a'', e ''ordem'' admite artigo feminino ''a''. A combinação a+a resulta em ''à''.')), rebuilt AS (SELECT sm.id,jsonb_agg(CASE WHEN f.pos IS NOT NULL THEN jsonb_set(jsonb_set(jsonb_set(e.value,'{q}',to_jsonb(f.q)),'{a}',to_jsonb(f.a)),'{why}',to_jsonb(f.why)) ELSE e.value END ORDER BY e.ordinality) quiz FROM study_materials sm CROSS JOIN LATERAL jsonb_array_elements(sm.quiz) WITH ORDINALITY e(value,ordinality) LEFT JOIN fixes f ON f.slug=sm.slug AND f.pos=e.ordinality WHERE sm.slug IN (SELECT DISTINCT slug FROM fixes) GROUP BY sm.id) UPDATE study_materials sm SET quiz=r.quiz,updated_at=now() FROM rebuilt r WHERE sm.id=r.id;